INSERT INTO `product` VALUES (3,'Le 5 A 7 Bea En Suede','Cabas souple décliné en suède. Léger et entièrement doublé de suède ton sur ton, il est muni d\'une patte de cuir ornée du cassandre et d\'une poche intérieure zippée. Spacieux et fonctionnel grâce à son format east/west, des lacets permettent de resserrer les côtés offrant ainsi différentes silhouettes. Bijouterie en laiton bronze. Dimensions : 50 x 28 x 18 cm. Hauteur anse : 28 cm. Cuir de veau. Style id 763435008IW3645. Pays de fabrication : Italie',5,3200.00,'Marron',NULL,NULL,NULL,NULL,'femme'),(4,'Calypso Large En Cuir D\'agneau Grainé','Le nouveau sac enveloppe signature de Saint Laurent. Souple, confectionné dans un cuir finement grainé à matelassage effet coussin. Cette version maxi est rehaussée d\'une chaîne gourmette coulissante. Souple et spacieux, son volume est idéal pour un usage quotidien. Doublure en gros-grain. Bijouterie en laiton light bronze. Fermoir aimanté. Poche interne zippée. Dimensions : 38 x 21 x 10 cm. Longueur de la chaîne : de 27 à 49 cm. Cuir d\'agneau, laiton. Style id 777399AACYT3212. Pays de fabrication : Italie',5,2950.00,'Marron',NULL,NULL,NULL,NULL,'femme'),(5,'Niki Medium En Cuir Vintage','Sac souple en cuir de veau vintage, surpiqué en chevrons et orné du cassandre. Spacieux, il dispose de deux compartiments et d\'une grande poche plaquée à l\'arrière. Sa bandoulière chaîne coulissante permet un porté épaule ou croisé. Cuir tanné sans chrome ni métal. Doublure en coton certifié. Bijouterie en laiton light bronze. Une poche extérieure à l\'arrière. Fermoir pression aimanté. Deux poches intérieures. Dimensions: 28 x 20 x 8,5 cm. Longueur de la chaîne: de 30 à 53 cm. Veau, laiton. Style id 6331840EN071000. Pays de fabrication : Italie',5,2700.00,'Noir',NULL,NULL,NULL,NULL,'femme'),(6,'Large Gaby Vanity Bag En Cuir D\'agneau','Large sac vanity orné de surpiqûres matelassées et du cassandre. Entièrement doublé de cuir, il offre de multiples portés. Sa bandoulière amovible est ajustable. Doublure en cuir. Bijouterie en laiton light bronze. Fermeture zippée. Une fente à carte. Dimensions: 22 x 15,5 x 8 cm. Longueur de la bandoulière: 53 cm. Hauteur de la poignée : 5,5 cm. Agneau laiton. Style id 8515721EL076195. Pays de fabrication : Italie',5,2200.00,'Rouge',NULL,NULL,NULL,NULL,'femme'),(7,'Voltaire Top Handle En Box Saint Laurent','Sac top handle en cuir box Saint Laurent orné du cassandre. Moderne et structuré, sa anse ajustable permet un porté à l\'épaule ou à la main. Doublure en suède. Bijouterie en laiton light bronze. Fermoir pression aimanté. Une poche plaquée. Dimensions : 24 x 19 x 5 cm. Hauteur anse : 16/28 cm. Cuir de veau laiton. Style id 8443410SX0W1997. Pays de fabrication : Italie',5,2100.00,'Gris',NULL,NULL,NULL,NULL,'femme'),(8,'Icarino En Cuir Nappa Matelassé','La version baby de l\'iconique icare en cuir d\'agneau nappa surpiqué et orné du cassandre. Moderne et léger, il se porte à la main. Doublure en cuir. Bijouterie en laiton light bronze. Fermeture zippée. Dimensions : 17/26 x 13 x 3 cm. Hauteur de la anse : 13,5 cm. Cuir d\'agneau, laiton. Style id 851689AAANG3775. Pays de fabrication : Italie',5,2490.00,'Vert',NULL,NULL,NULL,NULL,'femme'),(9,'Icarino En Cuir Nappa Matelassé','La version baby de l\'iconique icare en cuir d\'agneau nappa surpiqué et orné du cassandre. Moderne et léger, il se porte à la main. Doublure en cuir. Bijouterie en laiton light bronze. Fermeture zippée. Dimensions : 17/26 x 13 x 3 cm. Hauteur de la anse : 13,5 cm. Cuir d\'agneau, laiton. Style id 851689AAANG3775. Pays de fabrication : Italie',5,2490.00,'Rose',NULL,NULL,NULL,NULL,'femme'),(10,'Cassandre Large Pochette À Chaine En Cuir D\'agneau','Large pochette à chaine en cuir, ornée du cassandre. Moderne et versatile, sa chaîne maillon permet un porté épaule ou en pochette à la main. Doublure en cuir. Bijouterie en laiton light bronze. Fermeture par bouton-pression. Poche interne zippée. Dimensions : 29.5 x 18 x 5 cm. Longueur de la chaîne : 25 cm. Agneau, laiton. Style id 853610AACYT1000. Pays de fabrication : Italie',5,1500.00,'Noir',NULL,NULL,NULL,NULL,'femme'),(11,'Mini Evening Bag En Strass','Minaudière ornée du cassandre et brodée de strass. Sophistiqué et féminin, il se porte à la main pour une silhouette du soir. Bijouterie en laiton light bronze. Fermeture aimantée. Dimensions : 18,5 x 7,5 x 2,5 cm. Strass, laiton. Style id 819638JBO7W8472. Pays de fabrication : Italie',5,2900.00,'Or',NULL,NULL,NULL,NULL,'femme'),(12,'Jamie Mini Pochon Porté Épaule En Suède','La version mini du pochon porté épaule jamie en suède, orné de surpiqûres cassandre et carré rive gauche. Léger et compact, ce sac est muni d\'une bandoulière cuir et chaîne permettant un porté à l\'épaule ou en travers de la poitrine. Des cordons de serrage permettent de resserrer ou d\'élargir les côtés pour créer différentes silhouettes. Doublure en cuir. Détails en métal bronze. Fermeture par bouton-pression et cordon de serrage. Dimensions : 14,5 x 15,5 x 8 cm. Hauteur de la bandoulière : 50 cm. Cuir de veau métal. Style id 8591741U8P72916. Pays de fabrication : Italie',5,1950.00,'Marron',NULL,NULL,NULL,NULL,'femme'),(13,'Jeanne Slingbacks En Cuir Lisse','Escarpins à bout pointu carré en métal ornés du cassandre martelé, munis d\'une empeigne carrée et d\'un talon aiguille. Semelle en cuir. Bride cheville élastique. Hauteur totale du talon : 11 cm. Cassandre en métal doré. Cuir d\'agneau, laiton. Style id 800164AADX21000. Pays de fabrication : Italie',5,1350.00,'Noir',NULL,NULL,NULL,NULL,'femme'),(14,'Tribute Sandales À Plateforme En Cuir Verni','Sandales à talon aiguille mi-haut recouvert munies de brides entrecroisées, d\'une plateforme biseautée et d\'une bride cheville ajustable gravée Saint Laurent Paris. Deux hauteurs de talons disponibles. Hauteur totale du talon : 10,5 cm. Cambrure : 7,5 cm. Hauteur de la plateforme : 3 cm. Semelle en cuir. Bride cheville ajustable. Cuir de veau. Style id 535227B8I006031. Pays de fabrication : Italie',5,950.00,'Rose',NULL,NULL,NULL,NULL,'femme'),(15,'Tribute Mules En Cuir Lisse','Mules saint laurent en cuir tanné sans métal, agrémentées de brides entrecroisées. Nous vous conseillons de choisir une demi-pointure au-dessus de votre pointure habituelle. Cuir tanné sans chrome ni métal. Hauteur totale du talon : 0,5 cm. Semelle en cuir. Cuir de veau. Style id 571952BDA002206. Pays de fabrication : Italie',5,675.00,'Marron',NULL,NULL,NULL,NULL,'femme'),(16,'Mon Chéri Sandales En Suède À Strass','Sandales à strass et bout en amande à brides croisées, munies d\'un talon aiguille en métal recouvert de satin, de brides cheville à lacets et d\'un charm cerise. Semelle en cuir. Plaque ronde en métal gravé Saint Laurent sur la semelle intérieure. Bride cheville réglable. Hauteur du talon : 11 cm. Cuir de chèvre, cristal, résine, laiton. Style id 863530AAF555787. Pays de fabrication : Italie',5,3900.00,'Rose',NULL,NULL,NULL,NULL,'femme'),(17,'Opyum Sandales En Cuir Verni','Sandales à talon cassandre, munies d\'une bride ajustable à la cheville. Deux hauteurs de talons disponibles. Hauteur totale du talon : 11 cm. Semelle en cuir. Talon cassandre en métal doré vieilli. Ce produit peut également être livré sous le code 5576620NPKK1000. Cuir de veau. Style id 5576621TV1A1000. Pays de fabrication : Italie',5,1300.00,'Noir',NULL,NULL,NULL,NULL,'femme'),(18,'Opyum Mules En Crêpe Satin','Mules dotées d\'un talon cassandre, d\'un bout carré et de brides croisées. Soie certifiée et viscose certifiée. Semelle en cuir. Plaque ronde en métal gravé Saint Laurent sur la semelle intérieure. Hauteur du talon : 8,5 cm. Cassandre en métal bronze. Viscose, soie. Style id 8189319QAB15518. Pays de fabrication : Italie',5,1150.00,'Rose',NULL,NULL,NULL,NULL,'femme'),(19,'Opyum Escarpins En Cuir Verni','Escarpins à talon structuré cassandre dotés d\'une empeigne décolletée. Deux hauteurs de talons disponibles. Hauteur totale du talon : 11 cm. Semelle en cuir. Talon cassandre en métal doré vieilli. Ce produit peut également être livré sous le code 4720111TV1A1000. Cuir de veau. Style id 4720110NPKK1000. Pays de fabrication : Italie',5,1250.00,'Noir',NULL,NULL,NULL,NULL,'femme'),(20,'Loulou Slingbacks En Cuir Verni','Escarpins à bride arrière munis d\'un talon aiguille incurvé en métal massif doré et d\'un bout pointu en métal orné d\'un cabochon en résine. Semelle en cuir. Plaque ronde en métal gravé Saint Laurent sur la semelle intérieure. Bride arrière élastique. Hauteur du talon : 11 cm. Cuir de veau, cuir d\'agneau, acier, résine époxy. Style id 8272501TVA66231. Pays de fabrication : Italie',5,5700.00,'Rouge',NULL,NULL,NULL,NULL,'femme'),(21,'Diane Bottes En Cuir Grainé','Bottes à talon aiguille et bout en amande, munies d\'une bride cheville avec une boucle guillochée ornée du cassandre en métal. Semelle en cuir. Hauteur totale du talon : 10 cm. Cuir de veau. Style id 74379725V001000. Pays de fabrication : Italie',5,1850.00,'Noir',NULL,NULL,NULL,NULL,'femme'),(23,'Nœud papillon H Gourmette','Nœud papillon 100 % soie',2,260.00,'Rouge',NULL,NULL,NULL,NULL,'homme'),(24,'Cravate','Pensée pour une allure élégante, cette cravate en grenadine de soie est tissée en jacquard sur un métier traditionnel. Ce tissage complexe lui apporte un effet texturé.',2,300.00,'Rouge et blanc',NULL,NULL,NULL,NULL,'homme'),(25,'Cravate','Pensée pour une allure élégante, cette cravate en grenadine de soie est tissée en jacquard sur un métier traditionnel. Ce tissage complexe lui apporte un effet texturé.',2,300.00,'Noir/gris',NULL,NULL,NULL,NULL,'homme'),(26,'Nœud papillon H Gourmette','Nœud papillon 100 % soie',2,260.00,'Noir/gris/blanc',NULL,NULL,NULL,NULL,'homme'),(27,'Cravate','Objet d\'allure et lieu de narration, la cravate Hermès dessine toutes les libertés. Avec elle une seule règle, le plaisir de la porter !',2,255.00,'Multicolore',NULL,NULL,NULL,NULL,'homme'),(28,'Nœud papillon H Gourmette','Nœud papillon 100 % soie',2,260.00,'Gris clair / gris foncé',NULL,NULL,NULL,NULL,'homme'),(29,'Nœud papillon H Gourmette','Nœud papillon 100 % soie',2,260.00,'Marine / bleu clair',NULL,NULL,NULL,NULL,'homme'),(30,'Cravate','Objet d\'allure et lieu de narration, la cravate Hermès dessine toutes les libertés. Avec elle une seule règle, le plaisir de la porter !',2,255.00,'Anthracite',NULL,NULL,NULL,NULL,'homme'),(31,'Cravate','Objet d\'allure et lieu de narration, la cravate Hermès dessine toutes les libertés. Avec elle une seule règle, le plaisir de la porter !',2,255.00,'Bleu ciel',NULL,NULL,NULL,NULL,'homme'),(32,'Nœud papillon H Gourmette','Nœud papillon 100 % soie',2,260.00,'Gris clair',NULL,NULL,NULL,NULL,'homme'),(33,'Barénia Eau de parfum','Le parfumeur Christine Nagel crée son premier chypre pour Hermès, une fragrance sensuelle aux notes boisées à l\'inoubliable élégance. Barénia est un parfum de peau révélant une dualité : la force et la douceur.',2,168.00,'Ambre',NULL,NULL,NULL,NULL,'unisex'),(34,'24, Faubourg Eau délicate','Roman composé par Maurice Roucel en 1995, 24 Faubourg est une invitation à un voyage dont le soleil serait la destination. Éclat des fleurs blanches en tête, rayonnement du cœur floral enveloppé d\'iris, de bois et de mystère.',2,153.00,'Doré',NULL,NULL,NULL,NULL,'unisex'),(35,'Elixir des Merveilles Eau de parfum','Le parfumeur Jean-Claude Ellena intensifie la magie douce des Merveilles en composant l\'Élixir des Merveilles. Une nouvelle étoile joyeuse, un concentré de merveilleux.',2,287.00,'Ambre doré',NULL,NULL,NULL,NULL,'unisex'),(36,'Eau des Merveilles Bleue Eau de toilette','En 2017, le parfumeur d\'Hermès Christine Nagel crée Eau des Merveilles Bleue. Un nouveau regard sur la constellation des Merveilles, qui unit la magie de l\'océan à la couleur azurée du ciel.',2,270.00,'Bleu',NULL,NULL,NULL,NULL,'unisex'),(37,'Twilly d\'Hermès Eau Ginger Eau de parfum','Avec l\'eau de parfum Twilly d\'Hermès Eau Ginger, les filles d\'Hermès expriment un bonheur contagieux. Créée par le parfumeur d\'Hermès Christine Nagel, cette autre facette de Twilly d\'Hermès s\'impose par son esprit joyeux et solaire.',2,273.00,'Rose',NULL,NULL,NULL,NULL,'unisex'),(38,'Terre d\'Hermès Eau de toilette','En 2006, Jean-Claude Ellena crée Terre d\'Hermès, une eau reliant l\'homme à ses origines, aux sources de sa puissance créatrice. Terre d\'Hermès raconte la relation de l\'homme à la terre, son dialogue humble et harmonieux avec la nature et les éléments.',2,128.00,'Orange',NULL,NULL,NULL,NULL,'unisex'),(39,'Terre d\'Hermès Parfum','Terre d\'Hermès raconte la relation de l\'homme à la terre, son dialogue humble et harmonieux avec la nature et les éléments. En 2009, Jean-Claude Ellena donne une nouvelle densité à Terre d\'Hermès, en créant Terre d\'Hermès Parfum.',2,211.00,'Ambre',NULL,NULL,NULL,NULL,'unisex'),(40,'Un Jardin sur le Nil Eau de toilette','Créé en 2005, l\'eau de toilette Un Jardin sur le Nil évoque un voyage olfactif dans les îles-jardins à Assouan en Égypte. Le parfumeur Jean-Claude Ellena raconte dans cette composition ce fleuve synonyme de vie et de générosité.',2,145.00,'Vert',NULL,NULL,NULL,NULL,'unisex'),(41,'Eau d\'orange verte Eau de cologne','La toute première cologne de la maison Hermès est signée Françoise Caron en 1979. Devenue emblématique, elle se distingue par sa fraîcheur vive et verte.',2,186.00,'Vert',NULL,NULL,NULL,NULL,'unisex'),(42,'Voyage d\'Hermès Eau de toilette','Créée en 2010 par le parfumeur Jean-Claude Ellena, Voyage d\'Hermès est une invitation à la découverte, à la rencontre et au partage. La composition, aussi à l\'aise au masculin qu\'au féminin, raconte la relation profonde et originale que la Maison entretient avec le voyage.',2,134.00,'Ambre',NULL,NULL,NULL,NULL,'unisex'),(43,'Sneakers Leader','Sneakers emblématiques en sergé technique, veau et chèvre velours sur une semelle légère graphique, pour une silhouette urbaine et contemporaine.',2,1070.00,'Multicolore blanc',NULL,NULL,NULL,NULL,'homme'),(44,'Sneakers Master','Sneakers en veau souple sur une semelle ultra fine, pour un style vintage et minimaliste.',2,90.00,'Blanc',NULL,NULL,NULL,NULL,'homme'),(45,'Sneakers Trail','Sneakers emblématiques en veau et chèvre velours sur une semelle graphique contrastée, pour une silhouette urbaine et contemporaine.',2,950.00,'Multicolore blanc',NULL,NULL,NULL,NULL,'homme'),(46,'Sneakers Kid','Sneakers en veau et chèvre velours aux lignes épurées. Détail « H » signature discret pour une allure urbaine et contemporaine au quotidien.',2,810.00,'Noir',NULL,NULL,NULL,NULL,'homme'),(47,'Sneakers Jet','Sneakers en chèvre velours, jeu de contrastes et « H » signature, pour un look audacieux et néo-vintage.',2,960.00,'Gris et blanc',NULL,NULL,NULL,NULL,'homme'),(48,'Sneakers Day','Sneakers en chèvre velours sublimées par une boucle Kelly fonctionnelle, pour une silhouette urbaine et contemporaine. Vendues avec une deuxième paire de lacets.',2,1180.00,'Beige',NULL,NULL,NULL,NULL,'homme'),(49,'Sneakers Kid','Sneakers en chèvre velours aux lignes épurées. Détail « H » signature discret pour une allure urbaine et contemporaine au quotidien.',2,810.00,'Rose',NULL,NULL,NULL,NULL,'homme'),(50,'Sneakers Bouncing','Sneakers en veau et chèvre velours. Semelle graphique ultra légère pour une silhouette dynamique et contemporaine. Vendues avec une deuxième paire de lacets.',2,895.00,'Noir',NULL,NULL,NULL,NULL,'homme'),(51,'Sneakers Match','Sneakers en chèvre sport et veau aux lignes épurées sublimées par un « H en Biais » perforé, pour une allure urbaine et néo-vintage.',2,870.00,'Blanc',NULL,NULL,NULL,NULL,'homme'),(52,'Sneakers Jet','Sneakers en chèvre velours, jeu de contrastes et « H » signature, pour un look audacieux et néo-vintage. Vendues avec une deuxième paire de lacets.',2,960.00,'Rouge sépia',NULL,NULL,NULL,NULL,'homme'),(53,'Blouson à capuche Casaque','Blouson à capuche zippé « Casaque » en ripstop crispé. Capuche avec cordon de serrage, poignets côtelés, zip double curseur, poches zippées sur les côtés.',2,4900.00,'Vert chrome',NULL,NULL,NULL,NULL,'homme'),(54,'Blouson à capuche','Blouson à capuche zippé en double crêpe de coton et soie. Capuche avec cordon de serrage, col montant avec boutons-pression gravés « Hermès Paris », jeu de surpiqûres avec détail « H » au dos.',2,3500.00,'Marine',NULL,NULL,NULL,NULL,'homme'),(55,'Blouson droit','Blouson boutonné en serge suédée déperlante, doublure amovible tissée jacquard en laine vierge. Coupe droite, poches à rabat boutonnées sur les côtés.',2,6500.00,'Marine',NULL,NULL,NULL,NULL,'homme'),(56,'Blouson à capuche détails cuir','Blouson à capuche en super Toilovent imperméable. Capuche avec cordon de serrage, zip double curseur, patte de boutonnage en cuir d\'agneau gomme.',2,5400.00,'Café',NULL,NULL,NULL,NULL,'homme'),(57,'Blouson à capuche','Blouson à capuche zippé en double crêpe de coton et soie. Capuche avec cordon de serrage, col montant avec boutons-pression gravés « Hermès Paris », jeu de surpiqûres avec détail « H » au dos.',2,3500.00,'Marine',NULL,NULL,NULL,NULL,'homme'),(58,'Surchemise','Surchemise zippée « techno papier ». Col montant avec mentonnière et bouton-pression gravé « Hermès Paris », poches poitrine à rabat.',2,2800.00,'Menthe',NULL,NULL,NULL,NULL,'homme'),(59,'Blouson droit détail cuir','Blouson boutonné en serge de laine et cachemire. Coupe droite, col montant boutonné, poches à rabat boutonnées, fonds de poches en cuir d\'agneau lavable.',2,3900.00,'Taupe',NULL,NULL,NULL,NULL,'homme'),(60,'Blouson bord-côte réversible Cavalcadour métallisé','Blouson bord-côte zippé imprimé « Cavalcadour métallisé » en nylon et élasthanne, réversible super Toilovent imperméable. Col, poignets et bas de blouson côtelés.',2,4500.00,'Ardoise',NULL,NULL,NULL,NULL,'homme'),(61,'Pantalon de jogging Capsule Sport','Pantalon de jogging Capsule Sport en super Toilovent imperméable. Cordon de serrage à la taille, poches zippées sur les côtés, passepoil en Toilovent réfléchissante.',2,1800.00,'Ardoise',NULL,NULL,NULL,NULL,'homme'),(62,'S